     leftPadding: highlight.margins.left
     topPadding: highlight.margins.top
     rightPadding: highlight.margins.right
diff --git a/src/declarativeimports/plasmacomponents3/TextField.qml b/src/declarativeimports/plasmacomponents3/TextField.qml
index ea65dc088..45ccfbd2f 100644
--- a/src/declarativeimports/plasmacomponents3/TextField.qml
+++ b/src/declarativeimports/plasmacomponents3/TextField.qml
@@ -92,6 +92,8 @@ T.TextField {
         }
     }

+    T.ContextMenu.menu: Private.TextFieldContextMenu { }
+
     onTextChanged: MobileTextSelection.MobileTextActionsToolBar.shouldBeVisible = false;
     onPressed: event => MobileTextSelection.MobileTextActionsToolBar.shouldBeVisible = true;

diff --git a/src/declarativeimports/plasmacomponents3/private/TextFieldContextMenu.qml b/src/declarativeimports/plasmacomponents3/private/TextFieldContextMenu.qml
new file mode 100644
index 000000000..41f33664c
--- /dev/null
+++ b/src/declarativeimports/plasmacomponents3/private/TextFieldContextMenu.qml
@@ -0,0 +1,120 @@
+/*
+    SPDX-FileCopyrightText: 2020 Devin Lin <espidev@gmail.com>
+    SPDX-FileCopyrightText: 2021 Carl Schwan <carlschwan@kde.org>
+    SPDX-FileCopyrightText: 2023 ivan tkachenko <me@ratijas.tk>
+
+    SPDX-License-Identifier: LGPL-2.0-or-later
+*/
+
+
+import QtQuick
+import QtQuick.Templates as T
+import org.kde.plasma.components as PC3
+
+PC3.Menu {
+    id: root
+
+    readonly property T.TextField target: parent as T.TextField
+
+    function __hasSelectedText(): bool {
+        return target !== null
+        && target.selectedText !== "";
+    }
+
+    function __editable(): bool {
+        return target !== null
+        && !target.readOnly;
+    }
+
+    // Show actions which should normally be hidden for password field
+    function __showPasswordRestrictedActions(): bool {
+        return target !== null
+            && target.echoMode !== TextInput.PasswordEchoOnEdit
+            && target.echoMode !== TextInput.Password;
+    }
+
+    // Show text editing actions which should normally be hidden for password field
+    function __showPasswordRestrictedEditingActions(): bool {
+        return __showPasswordRestrictedActions() && !target.readOnly;
+    }
+
+    modal: true
+    popupType: T.Popup.Native
+
+    PC3.MenuItem {
+        action: T.Action {
+            icon.name: "edit-undo-symbolic"
+            text: qsTr("Undo")
+            shortcut: StandardKey.Undo
+        }
+        visible: root.__showPasswordRestrictedEditingActions()
+        enabled: root.target?.canUndo ?? false
+        onTriggered: root.target.undo();
+    }
+    PC3.MenuItem {
+        action: T.Action {
+            icon.name: "edit-redo-symbolic"
+            text: qsTr("Redo")
+            shortcut: StandardKey.Redo
+        }
+        visible: root.__showPasswordRestrictedEditingActions()
+        enabled: root.target?.canRedo ?? false
+        onTriggered: root.target.redo();
+    }
+    PC3.MenuSeparator {
+        visible: root.__showPasswordRestrictedEditingActions()
+    }
+    PC3.MenuItem {
+        action: T.Action {
+            icon.name: "edit-cut-symbolic"
+            text: qsTr("Cut")
+            shortcut: StandardKey.Cut
+        }
+        visible: root.__showPasswordRestrictedEditingActions()
+        enabled: root.__hasSelectedText()
+        onTriggered: root.target.cut();
+    }
+    PC3.MenuItem {
+        action: T.Action {
+            icon.name: "edit-copy-symbolic"
+            text: qsTr("Copy")
+            shortcut: StandardKey.Copy
+        }
+        visible: root.__showPasswordRestrictedActions()
+        enabled: root.__hasSelectedText()
+        onTriggered: root.target.copy()
+    }
+    PC3.MenuItem {
+        action: T.Action {
+            icon.name: "edit-paste-symbolic"
+            text: qsTr("Paste")
+            shortcut: StandardKey.Paste
+        }
+        visible: root.__editable()
+        enabled: root.target?.canPaste ?? false
+        onTriggered: root.target.paste();
+    }
+    PC3.MenuItem {
+        action: T.Action {
+            icon.name: "edit-delete-symbolic"
+            text: qsTr("Delete")
+            shortcut: StandardKey.Delete
+        }
+        visible: root.__editable()
+        enabled: root.__hasSelectedText()
+        onTriggered: root.target.remove(root.target.selectionStart, root.target.selectionEnd);
+    }
+    PC3.MenuSeparator {
+        visible: root.target !== null
+            && (root.__editable() || root.__showPasswordRestrictedActions())
+    }
+    PC3.MenuItem {
+        action: T.Action {
+            icon.name: "edit-select-all-symbolic"
+            text: qsTr("Select All")
+            shortcut: StandardKey.SelectAll
+        }
+        visible: root.target !== null
+        onTriggered: root.target.selectAll()
+    }
+}
-- 
