From b207bf102a2e8899b3ab042519380453aef10b35 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:02:43 +0100
Subject: [PATCH] klipper: keep popup open when focus moves to its own child
 windows

The clipboard popup hid itself whenever focus left it, including when
focus moved to a menu opened from it, such as a text field context menu.
It now stays open while the focused window is transient for the popup.

BUG: 525065
---
 klipper/klipperpopup.cpp | 7 +++++--
 1 file changed, 5 insertions(+), 2 deletions(-)

diff --git a/klipper/klipperpopup.cpp b/klipper/klipperpopup.cpp
index 6ebc0171e9..69a23d4d2e 100644
--- a/klipper/klipperpopup.cpp
+++ b/klipper/klipperpopup.cpp
@@ -122,9 +122,12 @@ void KlipperPopup::positionOnScreen()

 void KlipperPopup::onFocusWindowChanged(QWindow *focusWindow)
 {
-    if (focusWindow != this && (!focusWindow || focusWindow->objectName() != u"klipperActionPopupWindow")) {
-        hide();
+    for (QWindow *window = focusWindow; window; window = window->transientParent()) {
+        if (window == this || window->objectName() == u"klipperActionPopupWindow") {
+            return;
+        }
     }
+    hide();
 }

 #include "moc_klipperpopup.cpp"
-- 
